import * as THREE from 'three';
const $=s=>document.querySelector(s), scene=new THREE.Scene();
scene.background=new THREE.Color(0x9b7361);scene.fog=new THREE.FogExp2(0x8e7568,.012);
const camera=new THREE.PerspectiveCamera(73,innerWidth/innerHeight,.1,220);camera.position.set(0,1.68,7);
const renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.1;$('#scene').appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight(0xb7d9d3,0x263230,1.8));
const sun=new THREE.DirectionalLight(0xffc19b,2.1);sun.position.set(-25,38,18);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-55;sun.shadow.camera.right=55;sun.shadow.camera.top=55;sun.shadow.camera.bottom=-55;scene.add(sun);
const world=new THREE.Group();scene.add(world);const raycaster=new THREE.Raycaster();raycaster.far=3.5;const interactables=[];const keys={},clock=new THREE.Clock();
const player={pos:new THREE.Vector3(0,1.68,7),yaw:0,pitch:0,health:100,oxygen:100,warmth:100,water:100,food:100,medkit:1,flare:0,cells:0,started:false,paused:true,dead:false,won:false,terminal:false,beaconOn:false,time:0,move:new THREE.Vector2(),mobileMove:new THREE.Vector2(),near:null};
const mat=(color,roughness=1,emissive=0,ei=0)=>new THREE.MeshStandardMaterial({color,roughness,emissive,emissiveIntensity:ei});
const groundMat=mat(0x293d39),barkMat=mat(0x24302c),pineMat=mat(0x35463c),paleMat=mat(0x97aaa0),rockMat=mat(0x596760),orangeMat=mat(0xd67b4c,0.65,0x6a200e,.35),glowMat=mat(0x82e6c1,.42,0x47d7ae,2.4),blueGlow=mat(0x8bcfff,.4,0x4ab6ff,2.5),goldGlow=mat(0xffd18a,.5,0xff882f,2);
function groundY(x,z){return Math.sin(x*.17+z*.09)*.37+Math.cos(z*.18-x*.07)*.3+Math.sin(x*.07)*.24;}
const geo=new THREE.PlaneGeometry(180,180,90,90);geo.rotateX(-Math.PI/2);const pos=geo.attributes.position;const colors=[];for(let i=0;i<pos.count;i++){let x=pos.getX(i),z=pos.getZ(i),y=groundY(x,z);pos.setY(i,y);const tone=new THREE.Color().setHSL(.39+Math.sin(x*.1+z*.12)*.025,.18,.17+Math.sin(x*.19)*.015);colors.push(tone.r,tone.g,tone.b);}geo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));geo.computeVertexNormals();const ground=new THREE.Mesh(geo,new THREE.MeshStandardMaterial({vertexColors:true,roughness:1}));ground.receiveShadow=true;world.add(ground);
// Broken red-orange horizon and a huge pale moon.
const moon=new THREE.Mesh(new THREE.SphereGeometry(9,24,18),new THREE.MeshBasicMaterial({color:0xc2b7a3}));moon.position.set(-34,29,-96);scene.add(moon);
function addRock(x,z,s=1){const m=new THREE.Mesh(new THREE.DodecahedronGeometry(s,0),rockMat);m.position.set(x,groundY(x,z)+s*.45,z);m.scale.set(1.2,.72,.95);m.rotation.set(Math.random()*.4,Math.random()*5,Math.random()*.3);m.castShadow=true;m.receiveShadow=true;world.add(m);}
function addTree(x,z,s=1){const y=groundY(x,z),g=new THREE.Group();g.position.set(x,y,z);let trunk=new THREE.Mesh(new THREE.CylinderGeometry(.13*s,.24*s,2.5*s,5),barkMat);trunk.position.y=1.25*s;trunk.castShadow=true;g.add(trunk);for(let n=0;n<3;n++){let crown=new THREE.Mesh(new THREE.ConeGeometry((1.05-n*.2)*s,(2-n*.15)*s,6),n===1?pineMat:barkMat);crown.position.y=(2.25+n*.62)*s;crown.castShadow=true;g.add(crown);}world.add(g);}
// Deliberate clearing framed by a ring of wind-bent alien pines.
for(let i=0;i<100;i++){let a=Math.random()*Math.PI*2,r=14+Math.random()*52,x=Math.cos(a)*r,z=Math.sin(a)*r-8;if(Math.abs(x)<10&&z>-13&&z<14)continue;addTree(x,z,.75+Math.random()*.95);if(i%2===0)addRock(x+(Math.random()-.5)*3,z+2,.45+Math.random()*.9);}
// Wind-swept grass shards, kept sparse for mobile performance.
for(let i=0;i<430;i++){let x=(Math.random()-.5)*120,z=(Math.random()-.5)*120,y=groundY(x,z);if(Math.abs(x)<10&&z>-14&&z<13)continue;let blade=new THREE.Mesh(new THREE.ConeGeometry(.035,.3+Math.random()*.3,3),i%4?pineMat:glowMat);blade.position.set(x,y+.13,z);blade.rotation.z=(Math.random()-.5)*.4;world.add(blade);}
function makeNode(type,label,x,z,color,scale=1){let g=new THREE.Group();g.position.set(x,groundY(x,z),z);const orb=new THREE.Mesh(new THREE.IcosahedronGeometry(.28*scale,1),color);orb.position.y=.75*scale;orb.scale.set(1,1.25,1);orb.castShadow=true;g.add(orb);const ring=new THREE.Mesh(new THREE.TorusGeometry(.43*scale,.025*scale,5,20),color);ring.rotation.x=Math.PI/2;ring.position.y=.15;g.add(ring);const light=new THREE.PointLight(color.color,1.4,5);light.position.y=1;g.add(light);g.userData={type,label,active:true};world.add(g);interactables.push(g);return g;}
// The crash pod: a scorched, half-buried capsule with a blinking emergency mast.
const wreck=new THREE.Group();wreck.position.set(0,groundY(0,1),1);wreck.rotation.z=-.42;world.add(wreck);
const hull=new THREE.Mesh(new THREE.CylinderGeometry(1.5,1.7,4.2,9),mat(0x727d73,.82));hull.rotation.z=Math.PI/2;hull.position.y=1.25;hull.castShadow=true;hull.receiveShadow=true;wreck.add(hull);
const nose=new THREE.Mesh(new THREE.ConeGeometry(1.48,1.2,9),orangeMat);nose.rotation.z=-Math.PI/2;nose.position.set(2.6,1.25,0);wreck.add(nose);
for(let i=0;i<3;i++){let band=new THREE.Mesh(new THREE.TorusGeometry(1.25,.09,6,12),orangeMat);band.rotation.y=Math.PI/2;band.position.set(-1+i*1.5,1.25,0);wreck.add(band);}
const windowMesh=new THREE.Mesh(new THREE.CircleGeometry(.55,8),blueGlow);windowMesh.position.set(-1.35,1.4,.88);windowMesh.rotation.y=.4;wreck.add(windowMesh);
let mast=new THREE.Mesh(new THREE.CylinderGeometry(.05,.07,2.8,5),paleMat);mast.position.set(-2.2,2,0);wreck.add(mast);let blink=new THREE.PointLight(0xff6a4e,3,12);blink.position.set(-2.2,3.4,0);wreck.add(blink);
const console=makeNode('terminal','Open the escape pod recorder',-2.1,3.8,goldGlow,.82);console.position.y=groundY(-2.1,3.8);console.userData.label='Open the escape pod recorder';
