const objectives=[['Search the crash site','Find your bearings. Look for useful supplies.'],['Find three signal cells','The rescue beacon is beyond the pines. Recover its power cells.'],['Reach the rescue beacon','The signal cells are ready. Follow the beacon compass.'],['Activate the rescue beacon','Hold the beacon and give the stars a reason to answer.']];
let toastTimer;
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300);}
function record(title,text){$('#logTitle').textContent=title;$('#logText').textContent=text;}
