function getDirection(angle){let dirs=['N','NE','E','SE','S','SW','W','NW'];return dirs[Math.round(((angle*180/Math.PI+360)%360)/45)%8];}
function update(dt){if(!player.started||player.paused)return;player.time+=dt;
 const forward=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0)-player.mobileMove.y;
 const side=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+player.mobileMove.x;
 const mag=Math.hypot(forward,side)||1,speed=(keys.ShiftLeft||keys.ShiftRight?6.6:4.15)*Math.min(1,Math.hypot(forward,side));
 player.pos.x+=(Math.sin(player.yaw)*forward+Math.cos(player.yaw)*side)/mag*speed*dt;player.pos.z+=(-Math.cos(player.yaw)*forward+Math.sin(player.yaw)*side)/mag*speed*dt;
