 if(player.health<=0){player.dead=true;player.paused=true;showOverlay('#end');$('#end .kicker').textContent='FIELD REPORT · NO SIGNAL';$('#end h1').innerHTML='LOST TO<br><em>THE DARK.</em>' $('#end .subtitle').textContent='Erebus-7 keeps what it takes.';$('#end .story').textContent='Your recorder goes quiet beneath the black pines. The beacon waits for another survivor.';$('#end #again').textContent='TRY AGAIN';if(document.pointerLockElement)document.exitPointerLock();return;}
 let best=null,bestDist=4.5,look=new THREE.Vector3(Math.sin(player.yaw)*Math.cos(player.pitch),Math.sin(player.pitch),-Math.cos(player.yaw)*Math.cos(player.pitch));
 for(const n of interactables){if(!n.userData.active)continue;let target=new THREE.Vector3();n.getWorldPosition(target);if(n.userData.type==='beacon')target.y+=1.3;const v=target.clone().sub(camera.position),d=v.length(),dot=look.dot(v.normalize());if(d<bestDist&&dot>.48){best=n;bestDist=d;}}
 player.near=best;const prompt=$('#interact');if(best){prompt.textContent=`[ E ] ${best.userData.label.toUpperCase()}`;prompt.classList.add('show');}else prompt.classList.remove('show');
