 beaconOrb.rotation.y+=dt*.6;beaconHalo.rotation.z+=dt*.24;blink.intensity=2.2+Math.sin(player.time*5)*1.3;dust.position.x=Math.sin(player.time*.08)*1.5;syncHud();
}
